effect.shader:
void main() {
    int n = clamp(int(samples), 4, 48);
    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = float(i) / float(n) - 0.5;
        float ang = radians(rotate) * t;
        float c = cos(ang), s = sin(ang);
        vec2 p = acScreenNorm - vec2(0.5);
        p.x *= acAspect;
        p = vec2(p.x * c - p.y * s, p.x * s + p.y * c);
        p *= (1.0 + scale * t);
        p.x /= acAspect;
        vec2 u = p + vec2(0.5) + vec2(dx, dy) * t;
        soma += texture(inputImg, u);
    }
    fragColor = soma / float(n + 1);
}
